// Reservation Data Processing Script for n8n (Smart Column Detection)
// Processes Dutch hotel reservation data and converts to clean JSON
// Automatically detects column positions based on header names

// Dutch to English weekday mapping
const WEEKDAY_MAP = {
  'ma': 'Monday',
  'di': 'Tuesday',
  'wo': 'Wednesday',
  'do': 'Thursday',
  'vr': 'Friday',
  'za': 'Saturday',
  'zo': 'Sunday'
};

/**
 * Detect column mappings from header row
 * @param {array} rows - Array of row objects from Excel
 * @returns {object} - Mapping of field names to column keys, plus metadata
 */
function detectColumnMapping(rows) {
  // Header keywords to look for (Dutch)
  const headerPatterns = {
    createdAt: ['Aanmaak'],
    arrival: ['Aankomst'],
    departure: ['Vertrek'],
    nights: ['Nachten'],
    rateCode: ['Prijscode'],
    channel: ['Kanaal'],
    status: ['Res. status', 'Status'],
    cancelledAt: ['Geannuleerd op', 'Geannuleerd'],
    averagePrice: ['Gem. prijs'],
    totalPrice: ['Totaal']
  };

  const mapping = {
    columns: {},
    missingColumns: [],
    usedFallback: false,
    detectionMethod: 'header'
  };

  // Search through first 10 rows to find the header row
  for (let i = 0; i < Math.min(10, rows.length); i++) {
    const row = rows[i];

    // Check each column in this row
    for (const [key, value] of Object.entries(row)) {
      if (!value || typeof value !== 'string') continue;

      const cellValue = value.trim();

      // Check against each header pattern
      for (const [fieldName, patterns] of Object.entries(headerPatterns)) {
        for (const pattern of patterns) {
          if (cellValue === pattern) {
            mapping.columns[fieldName] = key;
            break;
          }
        }
      }
    }

    // If we found the required columns, we've found the header
    if (mapping.columns.arrival && mapping.columns.departure && mapping.columns.createdAt) {
      // Check for missing optional columns
      for (const fieldName of Object.keys(headerPatterns)) {
        if (!mapping.columns[fieldName]) {
          mapping.missingColumns.push(fieldName);
        }
      }
      return mapping;
    }
  }

  // Fallback to original column positions if no header found
  console.log('Warning: Could not detect header row, using default column positions');
  mapping.usedFallback = true;
  mapping.detectionMethod = 'fallback';
  mapping.columns = {
    createdAt: '_1',
    arrival: '_2',
    departure: '_3',
    nights: '_7',
    rateCode: '_8',
    channel: '_10',
    averagePrice: '_12',
    totalPrice: '_13',
    status: '_15',
    cancelledAt: '_21'
  };

  return mapping;
}

/**
 * Parse Dutch date format "DD-MM-YY" or "DD-MM-YYYY" and return ISO date "YYYY-MM-DD"
 * @param {string} dateStr - Date string like "07-10-24" or "07-10-2024"
 * @returns {string|null} - ISO formatted date "YYYY-MM-DD" or null
 */
function parseDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') {
    return null;
  }

  // Remove any whitespace
  const cleaned = dateStr.trim();

  // Match DD-MM-YY or DD-MM-YYYY format
  const match = cleaned.match(/^(\d{2})-(\d{2})-(\d{2,4})$/);

  if (!match) {
    return null;
  }

  const day = match[1];
  const month = match[2];
  let year = match[3];

  // Convert 2-digit year to 4-digit year
  if (year.length === 2) {
    const yearNum = parseInt(year, 10);
    // Assume 20xx for years 00-50, 19xx for years 51-99
    year = yearNum <= 50 ? `20${year}` : `19${year}`;
  }

  // Return ISO format: YYYY-MM-DD
  return `${year}-${month}-${day}`;
}

/**
 * Parse datetime format "DD-MM-YYYY HH:MM:SS" and return ISO format with time "YYYY-MM-DDTHH:MM:SS"
 * @param {string} datetimeStr - DateTime string like "07-10-2024 07:21:33"
 * @returns {string|null} - ISO formatted datetime "YYYY-MM-DDTHH:MM:SS" or null
 */
function parseDatetime(datetimeStr) {
  if (!datetimeStr || typeof datetimeStr !== 'string') {
    return null;
  }

  // Match DD-MM-YYYY HH:MM:SS format
  const match = datetimeStr.trim().match(/^(\d{2})-(\d{2})-(\d{4})\s(\d{2}):(\d{2}):(\d{2})$/);

  if (!match) {
    return null;
  }

  const day = match[1];
  const month = match[2];
  const year = match[3];
  const hours = match[4];
  const minutes = match[5];
  const seconds = match[6];

  // Return ISO format without timezone: YYYY-MM-DDTHH:MM:SS
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
}

/**
 * Parse price string and return numeric value
 * @param {string} priceStr - Price string like "82,65€" or "165,30€"
 * @returns {number|null} - Numeric price value or null
 */
function parsePrice(priceStr) {
  if (!priceStr || typeof priceStr !== 'string') {
    return null;
  }

  try {
    // Remove € symbol and whitespace
    const cleaned = priceStr.replace(/€/g, '').trim();

    // Replace comma with period for decimal
    const normalized = cleaned.replace(',', '.');

    // Parse to float
    const price = parseFloat(normalized);

    // Return null if invalid number
    return isNaN(price) ? null : price;
  } catch (error) {
    return null;
  }
}

/**
 * Calculate the weekday from an ISO date string "YYYY-MM-DD"
 * @param {string} dateStr - ISO date string "YYYY-MM-DD"
 * @returns {string} - English weekday name
 */
function getWeekday(dateStr) {
  if (!dateStr) {
    return null;
  }

  try {
    // Parse ISO format YYYY-MM-DD
    const date = new Date(dateStr + 'T00:00:00Z');

    if (isNaN(date.getTime())) {
      return null;
    }

    const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    return weekdays[date.getUTCDay()];
  } catch (error) {
    return null;
  }
}

/**
 * Calculate number of nights between arrival and departure
 * @param {string} arrivalDate - ISO arrival date "YYYY-MM-DD"
 * @param {string} departureDate - ISO departure date "YYYY-MM-DD"
 * @returns {number|null} - Number of nights
 */
function calculateNights(arrivalDate, departureDate) {
  if (!arrivalDate || !departureDate) {
    return null;
  }

  try {
    // Parse ISO format YYYY-MM-DD
    const arrival = new Date(arrivalDate + 'T00:00:00Z');
    const departure = new Date(departureDate + 'T00:00:00Z');

    if (isNaN(arrival.getTime()) || isNaN(departure.getTime())) {
      return null;
    }

    const diffTime = departure - arrival;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    return diffDays >= 0 ? diffDays : null;
  } catch (error) {
    return null;
  }
}

/**
 * Normalize channel name to standard format
 * @param {string} channel - Raw channel name
 * @returns {string} - Normalized channel name
 */
function normalizeChannel(channel) {
  if (!channel || typeof channel !== 'string') {
    return 'Unknown';
  }

  const normalized = channel.trim();

  // Map common variations to standard names
  const channelMap = {
    'booking-com': 'Booking.com',
    'booking.com': 'Booking.com',
    'expedia': 'Expedia',
    'hoteliers-com': 'Hoteliers.com',
    'direct-walk-in': 'Walk-in',
    'direct': 'Walk-in',
    'voordeeluitjes-ftc': 'Voordeeluitjes',
    'walk-in': 'Walk-in'
  };

  const lower = normalized.toLowerCase();
  return channelMap[lower] || normalized;
}

/**
 * Normalize rate code to standard format
 * @param {string} rateCode - Raw rate code
 * @returns {string} - Normalized rate code
 */
function normalizeRateCode(rateCode) {
  if (!rateCode || typeof rateCode !== 'string') {
    return 'Unknown';
  }

  return rateCode.trim();
}

/**
 * Check if a row is a valid data row and return validation details
 * @param {object} row - Row object
 * @param {object} mapping - Column mapping
 * @returns {object} - Validation result with isValid flag and reasons
 */
function validateDataRow(row, mapping) {
  const result = {
    isValid: true,
    errors: []
  };

  // A valid data row should have the required date fields
  const createdAt = row[mapping.columns.createdAt];
  const arrival = row[mapping.columns.arrival];
  const departure = row[mapping.columns.departure];

  if (!createdAt) {
    result.isValid = false;
    result.errors.push(`Missing creation date in column ${mapping.columns.createdAt}`);
  }

  if (!arrival) {
    result.isValid = false;
    result.errors.push(`Missing arrival date in column ${mapping.columns.arrival}`);
  }

  if (!departure) {
    result.isValid = false;
    result.errors.push(`Missing departure date in column ${mapping.columns.departure}`);
  }

  if (!result.isValid) {
    return result;
  }

  // Check if createdAt contains datetime pattern (DD-MM-YYYY HH:MM:SS)
  const datetimePattern = /^\d{2}-\d{2}-\d{4}\s\d{2}:\d{2}:\d{2}$/;
  const datePattern = /^\d{2}-\d{2}-\d{2,4}$/;

  if (!datetimePattern.test(createdAt)) {
    result.isValid = false;
    result.errors.push(`Invalid creation datetime format: "${createdAt}" (expected DD-MM-YYYY HH:MM:SS)`);
  }

  if (!datePattern.test(arrival)) {
    result.isValid = false;
    result.errors.push(`Invalid arrival date format: "${arrival}" (expected DD-MM-YY or DD-MM-YYYY)`);
  }

  if (!datePattern.test(departure)) {
    result.isValid = false;
    result.errors.push(`Invalid departure date format: "${departure}" (expected DD-MM-YY or DD-MM-YYYY)`);
  }

  return result;
}

/**
 * Process a single reservation row
 * @param {object} row - Row object from Excel
 * @param {object} mapping - Column mapping with metadata
 * @param {number} rowIndex - Row index for error reporting
 * @returns {object|null} - Processed reservation object with warnings or null
 */
function processReservation(row, mapping, rowIndex) {
  const warnings = [];
  const notes = [];

  // Add note if using fallback column detection
  if (mapping.usedFallback) {
    notes.push('Column detection used fallback positions (no header row found)');
  }

  // Add notes for missing columns
  if (mapping.missingColumns.length > 0) {
    notes.push(`Missing columns: ${mapping.missingColumns.join(', ')}`);
  }

  // Validate the row
  const validation = validateDataRow(row, mapping);

  if (!validation.isValid) {
    return null; // Skip invalid rows
  }

  // Extract and parse dates using detected column positions
  const createdAt = parseDatetime(row[mapping.columns.createdAt]);
  const arrivalDate = parseDate(row[mapping.columns.arrival]);
  const departureDate = parseDate(row[mapping.columns.departure]);
  const cancelledAt = mapping.columns.cancelledAt && row[mapping.columns.cancelledAt] ? 
    parseDatetime(row[mapping.columns.cancelledAt]) : null;

  // Check for date parsing failures
  if (!createdAt) {
    warnings.push(`Failed to parse creation date: "${row[mapping.columns.createdAt]}"`);
  }
  if (!arrivalDate) {
    warnings.push(`Failed to parse arrival date: "${row[mapping.columns.arrival]}"`);
  }
  if (!departureDate) {
    warnings.push(`Failed to parse departure date: "${row[mapping.columns.departure]}"`);
  }

  // Extract and parse prices
  const averagePrice = mapping.columns.averagePrice && row[mapping.columns.averagePrice] ? 
    parsePrice(row[mapping.columns.averagePrice]) : null;
  const totalPrice = mapping.columns.totalPrice && row[mapping.columns.totalPrice] ? 
    parsePrice(row[mapping.columns.totalPrice]) : null;

  // Add warnings for price parsing failures
  if (mapping.columns.averagePrice && row[mapping.columns.averagePrice] && averagePrice === null) {
    warnings.push(`Failed to parse average price: "${row[mapping.columns.averagePrice]}"`);
  }
  if (mapping.columns.totalPrice && row[mapping.columns.totalPrice] && totalPrice === null) {
    warnings.push(`Failed to parse total price: "${row[mapping.columns.totalPrice]}"`);
  }

  // Extract other fields
  const nightsFromData = mapping.columns.nights && row[mapping.columns.nights] ? 
    parseInt(row[mapping.columns.nights], 10) : null;
  const channel = mapping.columns.channel ? 
    normalizeChannel(row[mapping.columns.channel]) : 'Unknown';
  const rateCode = mapping.columns.rateCode ? 
    normalizeRateCode(row[mapping.columns.rateCode]) : 'Unknown';
  const status = mapping.columns.status && row[mapping.columns.status] ? 
    row[mapping.columns.status].trim() : null;

  // Calculate nights as verification (should match nightsFromData)
  const calculatedNights = calculateNights(arrivalDate, departureDate);
  const nights = nightsFromData !== null ? nightsFromData : calculatedNights;

  // Verify calculated vs provided nights if both exist
  if (nightsFromData !== null && calculatedNights !== null && nightsFromData !== calculatedNights) {
    warnings.push(`Nights mismatch: data says ${nightsFromData}, calculated ${calculatedNights}`);
  }

  // Get weekday for arrival date
  const weekdayArrival = getWeekday(arrivalDate);

  if (!weekdayArrival && arrivalDate) {
    warnings.push('Could not calculate weekday from arrival date');
  }

  // Build result object
  const result = {
    arrival_date: arrivalDate,
    nights: nights,
    departure_date: departureDate,
    created_at: createdAt,
    weekday_arrival: weekdayArrival,
    channel: channel,
    rate_code: rateCode
  };

  // Add prices if they exist
  if (averagePrice !== null) {
    result.average_price = averagePrice;
  }
  if (totalPrice !== null) {
    result.total_price = totalPrice;
  }

  // Only include cancelled_at if it exists
  if (cancelledAt) {
    result.cancelled_at = cancelledAt;
  }

  // Add warnings and notes if they exist
  if (warnings.length > 0) {
    result._warnings = warnings;
  }
  if (notes.length > 0) {
    result._notes = notes;
  }

  return result;
}

// ========== N8N EXECUTION CODE ==========

// Get input data from n8n
const items = $input.all();
const rows = items.map(item => item.json);

// Detect column mapping
const mapping = detectColumnMapping(rows);

// Process all rows
const processedReservations = [];

for (let i = 0; i < rows.length; i++) {
  const processed = processReservation(rows[i], mapping, i);

  // Only add valid reservations (skip null/invalid rows)
  if (processed) {
    processedReservations.push(processed);
  }
}

// Return in n8n format: array of objects with { json: data }
return processedReservations.map(reservation => ({
  json: reservation
}));

/**
 * Hotel Revenue Forecasting System - Module 2: Historical Analysis Engine
 * 
 * Calculates:
 * - Weekday baseline averages (room nights, revenue, ADR)
 * - Channel mix percentages
 * - Leadtime distribution (buckets + avg leadtime)
 * - Booking pace curves per weekday (CORRECTED LOGIC)
 * - Overall booking pace curve (all reservations, not weekday-bound)
 * - Revenue ratios (TotalRevenue / RoomRevenue), overall + per weekday
 * 
 * These calculations run ONCE and are reused for all forecast days
 */

class HistoricalAnalysisEngine {
  constructor(parsedData) {
    this.data = parsedData;
    this.analysis = {};
    this.warnings = [];
  }

  /**
   * Main analysis orchestrator
   */
  runAllAnalysis() {
    try {
      // Calculate weekday baseline averages
      this.analysis.weekdayBaselines = this.calculateWeekdayBaselines();

      // Calculate channel mix
      this.analysis.channelMix = this.calculateChannelMix();

      // Calculate leadtime distributions
      this.analysis.leadtimeDistribution = this.calculateLeadtimeDistribution();

      // Calculate booking pace curves (CORRECTED LOGIC)
      const bookingPaceCurvesResult = this.calculateBookingPaceCurves();
      this.analysis.leadtimeCurves = bookingPaceCurvesResult.weekdayCurves;
      this.analysis.overallLeadtimeCurve = bookingPaceCurvesResult.overallCurve;

      // Calculate revenue ratios
      this.analysis.revenueRatios = this.calculateRevenueRatios();

      return {
        success: true,
        analysis: this.analysis,
        warnings: this.warnings
      };

    } catch (error) {
      return {
        success: false,
        error: error.message,
        warnings: this.warnings
      };
    }
  }

  /**
   * Calculate weekday baseline averages from historical data
   * Groups by weekday and calculates mean values
   */
  calculateWeekdayBaselines() {
    const historicalData = this.data.historicalHousestate;

    if (!historicalData || historicalData.length === 0) {
      throw new Error('CRITICAL: No historical housestate data available. Cannot calculate baselines.');
    }

    if (historicalData.length < 365) {
      this.warnings.push(
        `WARNING: Only ${historicalData.length} days of historical data (recommended: 365+). This may affect forecast accuracy.`
      );
    }

    // Group by weekday
    const weekdayGroups = {
      'Monday': [],
      'Tuesday': [],
      'Wednesday': [],
      'Thursday': [],
      'Friday': [],
      'Saturday': [],
      'Sunday': []
    };

    historicalData.forEach(day => {
      if (weekdayGroups[day.weekday]) {
        weekdayGroups[day.weekday].push({
          roomNights: day.roomNights,
          roomRevenue: day.roomRevenue,
          totalRevenue: day.totalRevenue
        });
      }
    });

    // Calculate averages for each weekday
    const baselines = {};
    const missingWeekdays = [];

    Object.keys(weekdayGroups).forEach(weekday => {
      const days = weekdayGroups[weekday];

      if (days.length === 0) {
        missingWeekdays.push(weekday);
        return;
      }

      const avgRoomNights = days.reduce((sum, d) => sum + d.roomNights, 0) / days.length;
      const avgRoomRevenue = days.reduce((sum, d) => sum + d.roomRevenue, 0) / days.length;
      const avgTotalRevenue = days.reduce((sum, d) => sum + d.totalRevenue, 0) / days.length;
      const avgADR = avgRoomRevenue / avgRoomNights;

      baselines[weekday] = {
        avgRoomNights,
        avgRoomRevenue,
        avgTotalRevenue,
        avgADR,
        sampleSize: days.length
      };
    });

    if (missingWeekdays.length > 0) {
      throw new Error(
        `CRITICAL: Missing historical data for weekdays: ${missingWeekdays.join(', ')}. ` +
        `Need at least one data point per weekday.`
      );
    }

    return baselines;
  }

  /**
   * Calculate channel mix percentages
   */
  calculateChannelMix() {
    const reservations = this.data.historicalReservations;

    if (!reservations || reservations.length === 0) {
      throw new Error('CRITICAL: No historical reservations data available. Cannot calculate channel mix.');
    }

    // Group by channel
    const channelCounts = {};
    let totalRoomNights = 0;

    reservations.forEach(res => {
      const channel = res.channel || 'Unknown';
      if (!channelCounts[channel]) {
        channelCounts[channel] = 0;
      }
      channelCounts[channel] += res.roomNights;
      totalRoomNights += res.roomNights;
    });

    if (totalRoomNights === 0) {
      throw new Error('CRITICAL: No valid room nights in historical reservations. Cannot calculate channel mix.');
    }

    // Calculate percentages
    const channelMix = {};
    Object.keys(channelCounts).forEach(channel => {
      channelMix[channel] = {
        lastYear: (channelCounts[channel] / totalRoomNights) * 100,
        forecast: (channelCounts[channel] / totalRoomNights) * 100 // placeholder
      };
    });

    return channelMix;
  }

  /**
   * Calculate leadtime distribution
   * Groups bookings by leadtime buckets
   */
  calculateLeadtimeDistribution() {
    const reservations = this.data.historicalReservations;

    if (!reservations || reservations.length === 0) {
      throw new Error('CRITICAL: No historical reservations data. Cannot calculate leadtime distribution.');
    }

    // Filter out reservations with invalid leadtime
    const validReservations = reservations.filter(res => 
      res.leadtime !== null && res.leadtime >= 0
    );

    if (validReservations.length === 0) {
      throw new Error(
        'CRITICAL: No valid leadtime data in historical reservations. Check that Reservation_created_at dates are present.'
      );
    }

    // Buckets: 0-1d, 2-7d, 8-14d, 15-21d, 22-28d, 28+d
    const buckets = {
      '0-1d': 0,
      '2-7d': 0,
      '8-14d': 0,
      '15-21d': 0,
      '22-28d': 0,
      '28+d': 0
    };

    validReservations.forEach(res => {
      const lt = res.leadtime;
      if (lt <= 1) buckets['0-1d']++;
      else if (lt <= 7) buckets['2-7d']++;
      else if (lt <= 14) buckets['8-14d']++;
      else if (lt <= 21) buckets['15-21d']++;
      else if (lt <= 28) buckets['22-28d']++;
      else buckets['28+d']++;
    });

    const total = validReservations.length;

    // Convert to percentages
    const distribution = {};
    Object.keys(buckets).forEach(bucket => {
      distribution[bucket] = (buckets[bucket] / total) * 100;
    });

    // Calculate average leadtime
    const avgLeadtime = validReservations.reduce((sum, res) => sum + res.leadtime, 0) / total;

    return {
      buckets: distribution,
      avgLeadtime,
      sampleSize: total
    };
  }

  /**
   * Leadtime checkpoints:
   *  - 0 days (same day)
   *  - 1 day before
   *  - then every 2 days up to 90 days
   *  => 0, 1, 2, 4, 6, ..., 90
   */
  getLeadtimeCheckpoints() {
    const checkpoints = [0, 1];
    for (let d = 2; d <= 90; d += 2) {
      checkpoints.push(d);
    }
    return checkpoints;
  }

  /**
   * Calculate booking pace curves for curve-based forecasting
   * CORRECTED LOGIC: Shows "what % of final bookings are typically on books at X days out"
   * 
   * Returns:
   * - weekdayCurves: { Monday: {...}, Tuesday: {...}, ... }
   * - overallCurve: { day0: %, day1: %, ... } over ALL reservations
   */
  calculateBookingPaceCurves() {
    const reservations = this.data.historicalReservations;
    const housestate = this.data.historicalHousestate;

    if (!reservations || reservations.length === 0) {
      throw new Error('CRITICAL: No historical reservations data. Cannot calculate booking pace curves.');
    }

    if (!housestate || housestate.length === 0) {
      throw new Error('CRITICAL: No historical housestate data. Cannot calculate booking pace curves.');
    }

    // Get lookback window: 1 year ago + 6 weeks
    const lookbackWindow = this.getLookbackWindow();

    // Filter to lookback period
    const relevantReservations = reservations.filter(res => {
      const arrivalDate = new Date(res.arrivalDate);
      return arrivalDate >= lookbackWindow.start && arrivalDate <= lookbackWindow.end;
    });

    const relevantHousestate = housestate.filter(day => {
      const date = new Date(day.date);
      return date >= lookbackWindow.start && date <= lookbackWindow.end;
    });

    if (relevantReservations.length === 0) {
      throw new Error('CRITICAL: No reservations found in lookback window. Cannot calculate booking pace curves.');
    }

    if (relevantHousestate.length === 0) {
      throw new Error('CRITICAL: No housestate data found in lookback window. Cannot calculate booking pace curves.');
    }

    // Group housestate by weekday
    const stayDatesByWeekday = this.groupStayDatesByWeekday(relevantHousestate);

    const curves = {};
    const checkpoints = this.getLeadtimeCheckpoints();
    const missingWeekdays = [];

    // Calculate curves per weekday
    Object.keys(stayDatesByWeekday).forEach(weekday => {
      const stayDates = stayDatesByWeekday[weekday];

      if (stayDates.length === 0) {
        missingWeekdays.push(weekday);
        return;
      }

      const curvePoints = {};

      checkpoints.forEach(daysOut => {
        const percentages = [];

        stayDates.forEach(stayDateRecord => {
          const stayDate = new Date(stayDateRecord.date);
          const finalActual = stayDateRecord.roomNights;

          if (finalActual === 0) return; // Skip if no final room nights

          // Get all reservations for this stay date
          const reservationsForDate = relevantReservations.filter(res => {
            const arrivalDate = new Date(res.arrivalDate);
            return arrivalDate.getTime() === stayDate.getTime();
          });

          // Calculate OTB at this checkpoint
          let otbRoomNights = 0;

          reservationsForDate.forEach(res => {
            // Was this reservation on the books at 'daysOut' days before arrival?
            if (res.leadtime >= daysOut) {
              otbRoomNights += res.roomNights;
            }
          });

          // Calculate percentage
          const percentage = (otbRoomNights / finalActual) * 100;
          percentages.push(percentage);
        });

        // Average across all historical stay dates
        const avgPercentage = percentages.length > 0
          ? percentages.reduce((sum, pct) => sum + pct, 0) / percentages.length
          : 0;

        curvePoints[`day${daysOut}`] = avgPercentage;
      });

      curves[weekday] = curvePoints;
    });

    // Handle missing weekdays
    if (missingWeekdays.length > 0) {
      this.warnings.push(
        `WARNING: No booking pace data for ${missingWeekdays.join(', ')}. Using average curve as fallback.`
      );

      const averageCurve = this.calculateAverageCurve(curves);
      missingWeekdays.forEach(weekday => {
        curves[weekday] = averageCurve;
      });
    }

    // Calculate overall booking pace curve (not weekday-specific)
    const overallCurve = this.calculateOverallBookingPaceCurve(
      relevantReservations,
      relevantHousestate,
      checkpoints
    );

    return {
      weekdayCurves: curves,
      overallCurve
    };
  }

  /**
   * Get lookback window: 1 year ago + 6 weeks
   */
  getLookbackWindow() {
    const currentHousestate = this.data.currentHousestate;

    if (!currentHousestate || currentHousestate.length === 0) {
      throw new Error('CRITICAL: No current housestate data. Cannot determine lookback window.');
    }

    const forecastStartDate = new Date(currentHousestate[0].date);

    // 1 year ago
    const lookbackStart = new Date(forecastStartDate);
    lookbackStart.setFullYear(lookbackStart.getFullYear() - 1);

    // + 6 weeks
    const lookbackEnd = new Date(lookbackStart);
    lookbackEnd.setDate(lookbackEnd.getDate() + (6 * 7));

    return { start: lookbackStart, end: lookbackEnd };
  }

  /**
   * Group housestate records by weekday
   */
  groupStayDatesByWeekday(housestateRecords) {
    const groups = {
      'Monday': [],
      'Tuesday': [],
      'Wednesday': [],
      'Thursday': [],
      'Friday': [],
      'Saturday': [],
      'Sunday': []
    };

    housestateRecords.forEach(record => {
      if (groups[record.weekday]) {
        groups[record.weekday].push({
          date: record.date,
          roomNights: record.roomNights
        });
      }
    });

    return groups;
  }

  /**
   * Calculate overall booking pace curve (not per weekday)
   * Uses ALL stay dates with valid data
   */
  calculateOverallBookingPaceCurve(relevantReservations, relevantHousestate, checkpoints) {
    const overallCurve = {};

    checkpoints.forEach(daysOut => {
      const percentages = [];

      relevantHousestate.forEach(stayDateRecord => {
        const stayDate = new Date(stayDateRecord.date);
        const finalActual = stayDateRecord.roomNights;

        if (finalActual === 0) return;

        // Get all reservations for this stay date
        const reservationsForDate = relevantReservations.filter(res => {
          const arrivalDate = new Date(res.arrivalDate);
          return arrivalDate.getTime() === stayDate.getTime();
        });

        // Calculate OTB at this checkpoint
        let otbRoomNights = 0;

        reservationsForDate.forEach(res => {
          if (res.leadtime >= daysOut) {
            otbRoomNights += res.roomNights;
          }
        });

        const percentage = (otbRoomNights / finalActual) * 100;
        percentages.push(percentage);
      });

      // Average across all stay dates
      const avgPercentage = percentages.length > 0
        ? percentages.reduce((sum, pct) => sum + pct, 0) / percentages.length
        : 0;

      overallCurve[`day${daysOut}`] = avgPercentage;
    });

    return overallCurve;
  }

  /**
   * Calculate average curve from existing curves (used for missing weekdays)
   */
  calculateAverageCurve(curves) {
    const curveKeys = Object.keys(curves);
    if (curveKeys.length === 0) {
      throw new Error('CRITICAL: Cannot calculate average booking pace curve - no data available.');
    }

    const checkpoints = this.getLeadtimeCheckpoints();
    const avgCurve = {};

    checkpoints.forEach(days => {
      const key = `day${days}`;
      const values = curveKeys
        .map(weekday => curves[weekday][key])
        .filter(v => typeof v === 'number');

      avgCurve[key] = values.reduce((sum, val) => sum + val, 0) / values.length;
    });

    return avgCurve;
  }

  /**
   * Calculate revenue ratios (TotalRevenue / RoomRevenue)
   */
  calculateRevenueRatios() {
    const historicalData = this.data.historicalHousestate;

    if (!historicalData || historicalData.length === 0) {
      throw new Error('CRITICAL: No historical housestate data. Cannot calculate revenue ratios.');
    }

    const validDays = historicalData.filter(d => 
      d.roomRevenue > 0 && d.totalRevenue > 0
    );

    if (validDays.length === 0) {
      throw new Error('CRITICAL: No valid revenue data in historical housestate. Cannot calculate revenue ratios.');
    }

    const totalRoomRev = validDays.reduce((sum, d) => sum + d.roomRevenue, 0);
    const totalTotalRev = validDays.reduce((sum, d) => sum + d.totalRevenue, 0);
    const overallRatio = totalTotalRev / totalRoomRev;

    // Calculate per weekday
    const weekdayRatios = {};
    const weekdays = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

    weekdays.forEach(weekday => {
      const weekdayDays = validDays.filter(d => d.weekday === weekday);

      if (weekdayDays.length === 0) {
        weekdayRatios[weekday] = overallRatio;
        this.warnings.push(
          `WARNING: No revenue ratio data for ${weekday}. Using overall ratio: ${overallRatio.toFixed(2)}`
        );
      } else {
        const weekdayRoomRev = weekdayDays.reduce((sum, d) => sum + d.roomRevenue, 0);
        const weekdayTotalRev = weekdayDays.reduce((sum, d) => sum + d.totalRevenue, 0);
        weekdayRatios[weekday] = weekdayTotalRev / weekdayRoomRev;
      }
    });

    return {
      overallRatio,
      weekdayRatios
    };
  }

  /**
   * Get analysis summary for logging
   */
  getAnalysisSummary() {
    if (!this.analysis.weekdayBaselines) {
      return 'Analysis not yet run';
    }

    const summary = {
      weekdayBaselines: Object.keys(this.analysis.weekdayBaselines).map(day => ({
        day,
        avgRoomNights: this.analysis.weekdayBaselines[day].avgRoomNights.toFixed(1),
        avgADR: this.analysis.weekdayBaselines[day].avgADR.toFixed(2),
        sampleSize: this.analysis.weekdayBaselines[day].sampleSize
      })),
      channels: Object.keys(this.analysis.channelMix || {}).length,
      avgLeadtime: this.analysis.leadtimeDistribution.avgLeadtime?.toFixed(1) || 'N/A',
      overallRevenueRatio: this.analysis.revenueRatios.overallRatio.toFixed(2)
    };

    return summary;
  }
}

